from collections import Counter

def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    rc=Counter(r for r,c in pts); cc=Counter(c for r,c in pts)
    # Use the row/column containing the greatest number of markers as the spine.
    row_spine=max(rc.values()); col_spine=max(cc.values())
    if row_spine >= col_spine:
        spine=max(rc, key=lambda x: (rc[x], -abs(x-(min(r for r,c in pts)+max(r for r,c in pts))/2)))
        for c in range(min(c for r,c in pts), max(c for r,c in pts)+1):
            if out[spine][c]==0: out[spine][c]=3
        for r,c in pts:
            for rr in range(min(r,spine),max(r,spine)+1):
                if out[rr][c]==0: out[rr][c]=3
    else:
        spine=max(cc, key=lambda x: (cc[x], -abs(x-(min(c for r,c in pts)+max(c for r,c in pts))/2)))
        for r in range(min(r for r,c in pts), max(r for r,c in pts)+1):
            if out[r][spine]==0: out[r][spine]=3
        for r,c in pts:
            for c2 in range(min(c,spine),max(c,spine)+1):
                if out[r][c2]==0: out[r][c2]=3
    return out

